import{_ as a,o as l,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"Континентально-европейская социальная цивилизация","description":"","frontmatter":{},"headers":[],"relativePath":"ru/34-欧洲大陆社会型文明.md","filePath":"ru/34-欧洲大陆社会型文明.md","lastUpdated":null}'),o={name:"ru/34-欧洲大陆社会型文明.md"};function e(n,t,d,s,h,u){return l(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="континентально-европеиская-социальная-цивилизация" tabindex="-1">Континентально-европейская социальная цивилизация <a class="header-anchor" href="#континентально-европеиская-социальная-цивилизация" aria-label="Permalink to &quot;Континентально-европейская социальная цивилизация&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>34</td></tr><tr><td>Модуль</td><td>Типы цивилизаций и социальные системы</td></tr><tr><td>Ключевые слова</td><td>Континентально-европейский социальный, Социальный рынок, Соучастие труда и капитала, Консенсусная демократия, Сбалансированное развитие</td></tr></tbody></table><h2 id="i-происхождение-и-ядро-идеи" tabindex="-1">I. Происхождение и ядро идей <a class="header-anchor" href="#i-происхождение-и-ядро-идеи" aria-label="Permalink to &quot;I. Происхождение и ядро идей&quot;">​</a></h2><p>Континентально-европейский социальный — самый сбалансированный из пяти типов; истоки — в моделях континентальной Европы реального мира (Германия, Франция и др.). Долгим развитием сложилась «социальная рыночная экономика»: баланс эффективности рынка и социальной справедливости; гармония экономики и стабильности. После основания Симбиотической Цивилизации Якоря модель соединилась с идеями симбиоза — родился тип.</p><p>Ядро — восемь иероглифов: «социальный рынок, соучастие труда и капитала». Подробно:</p><ol><li><strong>Социальная рыночная экономика</strong>: рынок — основа распределения, эффективность; государство — корректировка провалов рынка, справедливость. «Максимум рынка, сколько нужно государства»</li><li><strong>Соучастие труда и капитала</strong>: в отношении труда и капитала (в культивации — рядовые культиваторы и держатели ресурсов, управление) — равный диалог, совместное решение; без доминирования одной стороны</li><li><strong>Консенсусная демократия</strong>: управление — консультации, диалог, консенсус; «выигрыш-выигрыш», не «нулевая сумма»</li><li><strong>Сбалансированное развитие</strong>: общий баланс экономики, общества, культуры, среды; не однобокость</li></ol><p>Совместимо с ядром: «прогресс Десяти Тысяч Рас» — общее развитие; «Больше Труда — Больше Награды» — справедливость; «Путь для Каждого» — права каждого.</p><h2 id="ii-социальная-структура" tabindex="-1">II. Социальная структура <a class="header-anchor" href="#ii-социальная-структура" aria-label="Permalink to &quot;II. Социальная структура&quot;">​</a></h2><p>«Среднее государство + сильные ассоциации + рынок + социальный диалог»:</p><table tabindex="0"><thead><tr><th>Элемент</th><th>Характеристика</th><th>Функция</th></tr></thead><tbody><tr><td>Среднее государство</td><td>Средние размер и функции; регулирование и защита</td><td>Рамка и защита</td></tr><tr><td>Сильные ассоциации</td><td>Профессиональные союзы, ассоциации, организации работодателей</td><td>Консультации, порядок</td></tr><tr><td>Рынок</td><td>Основное распределение</td><td>Эффективность</td></tr><tr><td>Социальный диалог</td><td>Трёхсторонние консультации</td><td>Координация, консенсус</td></tr></tbody></table><h3 id="_2-1-среднее-государство" tabindex="-1">2.1 Среднее государство <a class="header-anchor" href="#_2-1-среднее-государство" aria-label="Permalink to &quot;2.1 Среднее государство&quot;">​</a></h3><p>Типичное «социальное государство»:</p><ul><li>Макростабильность и порядок</li><li>Социальная защита: образование, медицина, жильё, пенсии</li><li>Регулирование рынка; против концентрации</li><li>Организация диалога; координация интересов</li></ul><p>Ядро — «субсидиарность»: государство не делает, что может общество; общество не делает, что может индивид; государство — только то, что не могут они.</p><h3 id="_2-2-сильные-ассоциации" tabindex="-1">2.2 Сильные ассоциации <a class="header-anchor" href="#_2-2-сильные-ассоциации" aria-label="Permalink to &quot;2.2 Сильные ассоциации&quot;">​</a></h3><ul><li><strong>Профсоюзы</strong>: интересы рядовых культиваторов</li><li><strong>Организации работодателей</strong>: интересы держателей ресурсов</li><li><strong>Профессиональные ассоциации</strong>: стандарты, сертификация</li><li><strong>Кооперативы</strong>: добровольные объединения</li></ul><p>Трёхуровневый диалог «государство—ассоциации—индивиды».</p><h3 id="_2-3-социальныи-диалог" tabindex="-1">2.3 Социальный диалог <a class="header-anchor" href="#_2-3-социальныи-диалог" aria-label="Permalink to &quot;2.3 Социальный диалог&quot;">​</a></h3><p>Ядро управления:</p><ul><li><strong>Трёхсторонние консультации</strong>: государство, культиваторы, держатели — регулярно</li><li><strong>Коллективные переговоры</strong>: ресурсы, условия, нормы продвижения</li><li><strong>Советы предприятий</strong>: в общинах и сектах — совместные решения</li></ul><p>Интересы согласуются; «выигрыш-выигрыш».</p><h2 id="iii-модель-культивации" tabindex="-1">III. Модель культивации <a class="header-anchor" href="#iii-модель-культивации" aria-label="Permalink to &quot;III. Модель культивации&quot;">​</a></h2><p>«Двойной путь, сотрудничество, баланс»:</p><h3 id="_3-1-двоиная-система" tabindex="-1">3.1 Двойная система <a class="header-anchor" href="#_3-1-двоиная-система" aria-label="Permalink to &quot;3.1 Двойная система&quot;">​</a></h3><ul><li><strong>Рыночный путь</strong>: рыночные институты и секты — по спросу</li><li><strong>Социальный путь</strong>: публичные институты — всеобщее образование</li></ul><p>Взаимодополнение: эффективность + справедливость.</p><h3 id="_3-2-школа—предприятие" tabindex="-1">3.2 Школа—предприятие <a class="header-anchor" href="#_3-2-школа—предприятие" aria-label="Permalink to &quot;3.2 Школа—предприятие&quot;">​</a></h3><ul><li><strong>Совместное строительство</strong>: учебные планы, таланты, исследования</li><li><strong>Ученичество</strong>: учёба и практика вместе</li><li><strong>Ротация талантов</strong>: обмен знаниями</li></ul><p>Тесная связь образования и практики; точность и эффективность.</p><h3 id="_3-3-сбалансированная-культивация" tabindex="-1">3.3 Сбалансированная культивация <a class="header-anchor" href="#_3-3-сбалансированная-культивация" aria-label="Permalink to &quot;3.3 Сбалансированная культивация&quot;">​</a></h3><ul><li>Теория и практика; не только уровень</li><li>Культивация и жизнь; отдых и семья</li><li>Индивид и общество; интеграция</li></ul><p>«Всесторонне развитый культиватор», не «машина».</p><h2 id="iv-подряд-связанныи-с-результатом" tabindex="-1">IV. Подряд, связанный с результатом <a class="header-anchor" href="#iv-подряд-связанныи-с-результатом" aria-label="Permalink to &quot;IV. Подряд, связанный с результатом&quot;">​</a></h2><p>«Подряд социального партнёрства»:</p><ol><li><strong>Многостороннее участие</strong>: культиваторы, наставники, управление — вместе</li><li><strong>Консультативное решение</strong>: планы — общим согласием</li><li><strong>Баланс интересов</strong>: без концентрации выгод</li><li><strong>Социальная ответственность</strong>: возможности новичкам, благо общин</li></ol><p>Плюс: координация, гармония, стабильность; чувство ответственности и принадлежности.</p><h2 id="v-преимущества-и-вызовы" tabindex="-1">V. Преимущества и вызовы <a class="header-anchor" href="#v-преимущества-и-вызовы" aria-label="Permalink to &quot;V. Преимущества и вызовы&quot;">​</a></h2><h3 id="_5-1-преимущества" tabindex="-1">5.1 Преимущества <a class="header-anchor" href="#_5-1-преимущества" aria-label="Permalink to &quot;5.1 Преимущества&quot;">​</a></h3><ul><li><strong>Стабильность</strong>: диалог гасит конфликты</li><li><strong>Сплочённость</strong>: консенсус и партнёрство</li><li><strong>Гармония труда и капитала</strong>: без острой конфронтации</li><li><strong>Баланс</strong>: всесторонность</li></ul><h3 id="_5-2-вызовы" tabindex="-1">5.2 Вызовы <a class="header-anchor" href="#_5-2-вызовы" aria-label="Permalink to &quot;5.2 Вызовы&quot;">​</a></h3><ul><li><strong>Медленные решения</strong>: консультации</li><li><strong>Издержки</strong>: сложные механизмы</li><li><strong>Сопротивление реформам</strong>: устоявшиеся интересы</li><li><strong>Внешняя конкуренция</strong>: не хватает напора</li></ul><p>Ответ: вбирает лучшее — эффективность восточноазиатского, инновации североамериканского.</p><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Самый сбалансированный тип: «социальный рынок, соучастие труда и капитала»; среднее государство, сильные ассоциации, рынок, диалог; двойной путь; подряд партнёрства. Сохраняя своё, ищет баланс рынка и общества, эффективности и справедливости.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>30-五种共生文明分型总览 (Обзор пяти типов симбиотических цивилизаций)</li><li>33-北美多元型文明 (Североамериканская плюралистическая цивилизация)</li><li>36-社会结构与阶层流动 (Социальная структура и мобильность классов)</li></ul>',46)])])}const p=a(o,[["render",e]]);export{_ as __pageData,p as default};
